import {createAssetLibrary} from './assets.js';
import {QUALITY,FrameSampler} from './performance.js';
import {orbitCamera} from './camera.js';
import {createSoftwareRenderer} from './software-renderer.js';
// Reusable, lazy, locally bundled Babylon/Havok scene lifecycle. No game-specific art.
const scripts=new Map();let enginePromise=null;
function script(url){if(scripts.has(url))return scripts.get(url);const p=new Promise((resolve,reject)=>{const e=document.createElement('script');e.src=url;e.onload=resolve;e.onerror=()=>{e.remove();scripts.delete(url);reject(Error('Could not load the local 3D engine. Reconnect and retry.'));};document.head.append(e);});scripts.set(url,p);return p;}
export async function load3D(){if(!enginePromise)enginePromise=(async()=>{await script('vendor/3d/babylon.js');await script('vendor/3d/loaders.js');await script('vendor/3d/HavokPhysics.js');const B=globalThis.BABYLON;const hk=await globalThis.HavokPhysics({locateFile:name=>new URL('vendor/3d/'+name,document.baseURI).href});return{B,hk};})().catch(e=>{enginePromise=null;throw e;});return enginePromise;}
export {QUALITY};
export async function create3DScene(canvas,{quality='medium',camera:cameraOptions={},lighting={},onError=e=>console.error('3D frame',e)}={}){const{B,hk}=await load3D();let engine,software=false;try{engine=new B.Engine(canvas,true,{preserveDrawingBuffer:false,stencil:true,powerPreference:'high-performance',audioEngine:false},false);}catch{software=true;engine=new B.NullEngine({renderWidth:900,renderHeight:550,textureSize:512,deterministicLockstep:false,lockstepMaxSteps:4});}if(software)engine.getCaps().maxVertexUniformVectors=256;const scene=new B.Scene(engine);scene.useRightHandedSystem=true;scene.clearColor=new B.Color4(.66,.79,.85,1);scene.enablePhysics(new B.Vector3(0,-9.81,0),new B.HavokPlugin(true,hk));scene.getPhysicsEngine().setTimeStep(1/60);scene.getPhysicsEngine().setSubTimeStep(1000/60);scene.physicsEnabled=false;const cameraRig=orbitCamera(B,scene,cameraOptions),camera=cameraRig.camera;const hemi=new B.HemisphericLight('sky',new B.Vector3(.2,1,.3),scene);hemi.intensity=lighting.ambient??.82;hemi.groundColor=B.Color3.FromHexString('#64705c');const sun=new B.DirectionalLight('sun',new B.Vector3(-.6,-1,-.5),scene);sun.position=new B.Vector3(12,22,10);sun.intensity=lighting.sun??1.7;const assets=createAssetLibrary({B,scene}),sampler=new FrameSampler();let failure=null,shadows=null,disposed=false,current=quality,paused=true,last=performance.now(),update=()=>{},resize=new ResizeObserver(()=>engine.resize());resize.observe(canvas);
 function setQuality(q){current=QUALITY[q]?q:'medium';const c=QUALITY[current];engine.setHardwareScalingLevel(c.scale);shadows?.dispose();shadows=c.shadows&&!software?new B.ShadowGenerator(c.shadows,sun):null;if(shadows){shadows.usePercentageCloserFiltering=true;shadows.filteringQuality=B.ShadowGenerator.QUALITY_LOW;}engine.resize();}
 setQuality(quality);const softwareRenderer=software?createSoftwareRenderer(canvas,B,scene,engine):null;function loop(){if(disposed||document.hidden)return;const now=performance.now(),rawMs=now-last,dt=Math.min(rawMs/1000,.1);last=now;sampler.add(rawMs);engine.beginFrame();try{update(paused?0:dt,{frameMs:rawMs,wallTime:now,paused});scene.render();softwareRenderer?.render();}catch(e){failure=e;paused=true;scene.physicsEnabled=false;scene.animationsEnabled=false;engine.stopRenderLoop(loop);onError(e);}engine.endFrame();}
 engine.runRenderLoop(loop);return{B,scene,engine,assets,canvas,camera,cameraRig,software,get failure(){return failure;},get shadows(){return shadows;},get quality(){return current;},setQuality(q){setQuality(q);},setUpdate(fn){update=fn;},pause(v){paused=v;last=performance.now();scene.physicsEnabled=!v;scene.animationsEnabled=!v;},stats(){return{...sampler.report(),fps:software?softwareRenderer.fps:Math.round(engine.getFps()),triangles:softwareRenderer?.triangles||0,meshes:scene.getActiveMeshes().length,draws:engine._drawCalls?.current||0,bodies:scene.getPhysicsEngine()?.getBodies().length||0,vertices:scene.getTotalVertices()};},dispose(){if(disposed)return;disposed=true;resize.disconnect();engine.stopRenderLoop(loop);assets.dispose();scene.dispose();engine.dispose();}};}
